refentry.refsect1:
&reftitle.description;
stringnullvar_export mixedvalue boolreturn&false;
var_export restituisce informazioni strutturate sulla data variabile. È simile a var_dump con una differenza: la rappresentazione restituita è codice PHP valido.

&reftitle.changelog;
&Version; &Description;
8.2.0
I nomi delle classi esportate ora sono completamente qualificati; in precedenza, il backslash iniziale veniva omesso.
7.3.0
Ora esporta gli oggetti stdClass come un array convertito in oggetto ((object) array( ... )), invece di usare il metodo inesistente stdClass::__setState. L'effetto pratico è che ora stdClass è esportabile, e il codice risultante funzionerà anche sulle versioni precedenti di PHP.

  &reftitle.examples;



    Esempi di var_export


<?php
$a = array (1, 2, array ("a", "b", "c"));
var_export($a);
?>


    &example.outputs;


array (
  0 => 1,
  1 => 2,
  2 => 
  array (
    0 => 'a',
    1 => 'b',
    2 => 'c',
  ),
)




<?php

$b = 3.1;
$v = var_export($b, true);
echo $v;

?>


    &example.outputs;


3.1







    Esportazione di stdClass (a partire da PHP 7.3.0)


<?php
$person = new stdClass;
$person->name = 'ElePHPant ElePHPantsdotter';
$person->website = 'https://php.net/elephpant.php';

var_export($person);


    &example.outputs;


(object) array(
   'name' => 'ElePHPant ElePHPantsdotter',
   'website' => 'https://php.net/elephpant.php',
)







    Esportazione di classi


<?php
class A { public $var; }
$a = new A;
$a->var = 5;
var_export($a);
?>


    &example.outputs;


\A::__set_state(array(
   'var' => 5,
))







    Utilizzo di __set_state()


<?php
class A
{
    public $var1;
    public $var2;

    public static function __set_state($an_array)
    {
        $obj = new A;
        $obj->var1 = $an_array['var1'];
        $obj->var2 = $an_array['var2'];
        return $obj;
    }
}

$a = new A;
$a->var1 = 5;
$a->var2 = 'foo';

eval('$b = ' . var_export($a, true) . ';'); // $b = A::__set_state(array(
                                            //    'var1' => 5,
                                            //    'var2' => 'foo',
                                            // ));
var_dump($b);
?>


    &example.outputs;


object(A)#2 (2) {
  ["var1"]=>
  int(5)
  ["var2"]=>
  string(3) "foo"
}
